    acc[p.category] = (acc[p.category] || 0) + 1;
    return acc;
  }, {});
}

function countByModule(problems) {
  return problems.reduce((acc, p) => {
    acc[p.module] = (acc[p.module] || 0) + 1;
    return acc;
  }, {});
}

function sprintDaysNeeded(total, perDay) {
  return Math.ceil(total / perDay);
}

