solution.code:
function completedOnTime(problem, timeUsed) {
  return timeUsed <= problem.target;
}

function sprintProgress(sprint, solves) {
  const solveMap = new Map(solves.map(s=>[s.id,s.timeUsed]));
  let onTime=0,overTime=0;
  for(const p of sprint){
    if(solveMap.has(p.id)){
      if(solveMap.get(p.id)<=p.target)onTime++;else overTime++;
    }
  }
  return{completed:solves.length,onTime,overTime,remaining:sprint.length-solves.length};
}

function avgTimeOverrun(sprint, solves) {
  const sprintMap=new Map(sprint.map(p=>[p.id,p.target]));
  const overruns=solves.filter(s=>sprintMap.has(s.id)&&s.timeUsed>sprintMap.get(s.id))
    .map(s=>s.timeUsed-sprintMap.get(s.id));
  return overruns.length?overruns.reduce((a,b)=>a+b,0)/overruns.length:0;
}

